				a[i%3]-=mn;
				b[t2]-=mn;
			}
		}
	}
	public static int s(int[] a, int[] b) {
		int ans = Math.min(a[0], b[1]);
		ans += Math.min(a[1], b[2]);
		ans += Math.min(a[2], b[0]);
		return ans;
	}
	public static void main(String[] args) {
		Reader in = new Reader();
		Writer out = new Writer();
		solve(in, out);
		out.exit();
	}
}
